export function translateInventory(value:string,language:InventoryLanguage):string {
 if(language==='en'||!value)return value;
 const lead=value.match(/^\s*/)?.[0]||'',trail=value.match(/\s*$/)?.[0]||'',key=value.trim();
 const exact=directSalesBengali[key]||inventoryErrors[key]||inventoryBengali[key]||legacyBengali[key];if(exact)return lead+exact+trail;
 const dynamic:[RegExp,(m:RegExpMatchArray)=>string][]=[
  [/^Remove line (\d+)$/,m=>`পণ্যের ${m[1]} নম্বর লাইন সরান`],
  [/^Line (\d+) quantity$/,m=>`${m[1]} নম্বর লাইনের পরিমাণ`],
  [/^Only (\d+) additional raw pieces are available\.$/,m=>`আর মাত্র ${m[1]} পিস সাদা মাল আছে।`],
  [/^(\d+) days$/,m=>`${m[1]} দিন`],
 ];
 for(const [pattern,make]of dynamic){const match=key.match(pattern);if(match)return lead+make(match)+trail;}
 return value;
}
